use verus::prelude::*;

#[verifier(pure)]
#[requires(health >= 0)]
#[requires(strength > 0)]
#[ensures(|ret: i64| ret >= 0)]
#[ensures(|ret: i64| ret * (strength as i64) >= (health as i64))]
#[ensures(|ret: i64| (ret == 0) || ((ret - 1) * (strength as i64) < (health as i64)))]
fn exec_turns_to_defeat(health: i8, strength: i8) -> i64 {
    // Compute ceil(health / strength) = (health + strength - 1) / strength
    let h = health as i64;
    let s = strength as i64;
    (h + s - 1) / s
}

#[verifier(pure)]
#[requires(a >= 0)]
#[requires(b > 0)]
#[requires(c >= 0)]
#[requires(d > 0)]
#[ensures(|ret: String|
    if ret == "Yes".to_string() {
        // if we say "Yes", Takahashi does not lose,
        // i.e. he defeats Aoki in no more turns than vice versa
        exec_turns_to_defeat(c, b) <= exec_turns_to_defeat(a, d)
    } else {
        // otherwise he would lose: he needs strictly more turns
        exec_turns_to_defeat(c, b) > exec_turns_to_defeat(a, d)
    }
)]
fn solve(a: i8, b: i8, c: i8, d: i8) -> String {
    // Takahashi needs this many attacks to defeat Aoki
    let takahashi_turns = exec_turns_to_defeat(c, b);
    // Aoki needs this many attacks to defeat Takahashi
    let aoki_turns = exec_turns_to_defeat(a, d);

    if takahashi_turns <= aoki_turns {
        "Yes".to_string()
    } else {
        "No".to_string()
    }
}